/**
 * Where attachments live: the local filesystem (Node/Docker) or an R2 bucket
 * (Cloudflare). Keys are generated by the server (`<workspaceId>/<uuid>`),
 * never derived from user input.
 */
export interface AttachmentStorage {
  /**
   * Streams exactly `size` bytes from `body` into `key`. Rejects, keeping
   * nothing, if the stream fails or its length differs.
   */
  put(key: string, body: ReadableStream<Uint8Array>, size: number, contentType: string): Promise<void>
  stream(key: string): Promise<ReadableStream | null>
  delete(key: string): Promise<void>
  deleteWorkspace(workspaceId: string): Promise<void>
  /** Removes every stored file (uninstalling the copy). */
  deleteAll(): Promise<void>
  /** Removes stored files that no database row references and that are older than `minAgeMs`. */
  sweep(isKnown: (key: string) => Promise<boolean>, minAgeMs?: number): Promise<number>
}

export const STORAGE_KEY = /^[0-9a-f-]{36}\/[0-9a-f-]{36}$/
export const WORKSPACE_ID = /^[0-9a-f-]{36}$/
